using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using PclRestore;
class InstallerTests {
 static byte[] original;static string root;static int count;static readonly List<string> results=new List<string>();
 static void Assert(bool yes,string why){if(!yes)throw new Exception(why);}
 static void Reject(Action a,string why){bool rejected=false;try{a();}catch{rejected=true;}Assert(rejected,why);}
 static string Case(string name,bool config=true){string dir=Path.Combine(root,name);Directory.CreateDirectory(dir);string exe=Path.Combine(dir,"Plain Craft Launcher 2.exe");File.WriteAllBytes(exe,original);if(config){Directory.CreateDirectory(Path.Combine(dir,"PCL"));File.WriteAllText(Path.Combine(dir,"PCL","Setup.ini"),"Theme:0\r\nLaunchFolderSelect:old-root\\\r\nSystemSystemUpdate:0\r\nUnrelated:保留我\r\n",new UTF8Encoding(true));}Directory.CreateDirectory(Path.Combine(dir,".minecraft","saves","first"));File.WriteAllText(Path.Combine(dir,".minecraft","saves","first","level.dat"),"DO NOT MODIFY: test save sentinel");return exe;}
 static string Config(string exe){return Path.Combine(Path.GetDirectoryName(exe),"PCL","Setup.ini");}
 static void Sentinel(string exe){Assert(File.ReadAllText(Path.Combine(Path.GetDirectoryName(exe),".minecraft","saves","first","level.dat"))=="DO NOT MODIFY: test save sentinel","Game files changed");}
 static void Test(string name,Action action){action();count++;results.Add("PASS "+name);Console.WriteLine("PASS "+name);}
 static void Main(string[] a){try{Run(a);}catch(Exception e){Console.WriteLine("FAIL "+e.GetType().Name+": "+e.Message);Environment.ExitCode=1;}}
 static void Run(string[] a){
  if(a.Length!=2)throw new Exception("Expected original EXE and NEW test root arguments");
  original=File.ReadAllBytes(a[0]);Assert(PatchEngine.Hash(original)==PatchEngine.OriginalHash,"Wrong test input");root=Path.GetFullPath(a[1]);Assert(!Directory.Exists(root)&&!File.Exists(root),"Test root must not exist");Directory.CreateDirectory(root);
  Test("exact binary reconstruction",()=>{var b=PatchEngine.Apply(original,PatchEngine.Resource("restore.patch.gz"));Assert(PatchEngine.Hash(b)==PatchEngine.PatchedHash,"Patch hash");});
  Test("install, preserve unrelated settings, select local game root, restore exact original bytes",()=>{
   string exe=Case("roundtrip");byte[] before=File.ReadAllBytes(Config(exe));string game=Path.Combine(Path.GetDirectoryName(exe),".minecraft");Directory.CreateDirectory(Path.Combine(game,"versions"));
   var result=PatchEngine.Install(exe,true,game);Assert(PatchEngine.HashFile(exe)==PatchEngine.PatchedHash,"Installed hash");Assert(File.ReadAllText(Config(exe)).Contains("Unrelated:保留我"),"Other settings changed");Assert(File.ReadAllText(Config(exe)).Contains("SystemSystemUpdate:2"),"Update setting");Assert(File.ReadAllText(Config(exe)).Contains("LaunchFolderSelect:"+game+"\\"),"Game root setting");
   int backups=Directory.GetDirectories(Path.GetDirectoryName(result.Backup)).Length;PatchEngine.Install(exe,true,game);Assert(Directory.GetDirectories(Path.GetDirectoryName(result.Backup)).Length==backups,"Repeated install wrote backup");
   PatchEngine.Restore(exe);Assert(File.ReadAllBytes(exe).SequenceEqual(original),"Original not restored exactly");Assert(File.ReadAllBytes(Config(exe)).SequenceEqual(before),"Config not restored exactly");Sentinel(exe);
  });
  Test("unknown executable rejected without any writes",()=>{string exe=Case("unknown");var b=original.ToArray();b[100]^=1;File.WriteAllBytes(exe,b);string h=PatchEngine.HashFile(exe),c=PatchEngine.HashFile(Config(exe));Reject(()=>PatchEngine.Install(exe,true,null),"Unknown accepted");Assert(PatchEngine.HashFile(exe)==h&&PatchEngine.HashFile(Config(exe))==c,"Unknown file changed");Assert(!Directory.Exists(Path.Combine(Path.GetDirectoryName(exe),"PCL","LocalRestoreBackups")),"Unknown created backups");Sentinel(exe);});
  Test("running or locked executable rejected",()=>{string exe=Case("locked-exe");using(var f=new FileStream(exe,FileMode.Open,FileAccess.Read,FileShare.Read)){Reject(()=>PatchEngine.Install(exe,true,null),"Locked EXE accepted");}Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"Locked EXE changed");Sentinel(exe);});
  Test("locked configuration rejected before executable write",()=>{string exe=Case("locked-config");using(var f=new FileStream(Config(exe),FileMode.Open,FileAccess.Read,FileShare.Read)){Reject(()=>PatchEngine.Install(exe,true,null),"Locked config accepted");}Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"EXE changed on config lock");Sentinel(exe);});
  foreach(string phase in new[]{"exe-written","config-written"}) {
   string stop=phase;Test("failure at "+phase+" rolls back executable and settings",()=>{string exe=Case("failure-"+stop);byte[] before=File.ReadAllBytes(Config(exe));Reject(()=>PatchEngine.InstallCore(exe,true,null,PatchEngine.Resource("restore.patch.gz"),s=>{if(s==stop)throw new IOException("simulated interruption");}),"Failure did not propagate");Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"Failure left patched EXE");Assert(File.ReadAllBytes(Config(exe)).SequenceEqual(before),"Failure changed config");Sentinel(exe);});
  }
  Test("restore preserves settings changed after installation",()=>{string exe=Case("edited-config");PatchEngine.Install(exe,true,null);File.AppendAllText(Config(exe),"LaterSetting:keep\r\n");byte[] edited=File.ReadAllBytes(Config(exe));var o=PatchEngine.Restore(exe);Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"Restore hash");Assert(File.ReadAllBytes(Config(exe)).SequenceEqual(edited),"Later settings lost");Assert(o.Message.Contains("保留"),"No preservation notice");Sentinel(exe);});
  Test("install and rollback work without any existing configuration",()=>{string exe=Case("no-config",false);PatchEngine.Install(exe,true,null);Assert(File.Exists(Config(exe)),"Default setting absent");PatchEngine.Restore(exe);Assert(!File.Exists(Config(exe)),"Created config not removed");Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"Restore hash");Sentinel(exe);});
  Test("opt-out leaves configuration bytes unchanged",()=>{string exe=Case("opt-out");byte[] before=File.ReadAllBytes(Config(exe));PatchEngine.Install(exe,false,null);Assert(File.ReadAllBytes(Config(exe)).SequenceEqual(before),"Opt-out ignored");PatchEngine.Restore(exe);Sentinel(exe);});
  Test("invalid game root rejected before any writes",()=>{string exe=Case("invalid-game");Reject(()=>PatchEngine.Install(exe,true,Path.Combine(root,"missing-world")),"Missing game root accepted");Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"Invalid root changed EXE");Sentinel(exe);});
  Test("corrupt patch rejected before backup or executable write",()=>{string exe=Case("corrupt-patch");byte[] p=PatchEngine.Resource("restore.patch.gz");p[p.Length/2]^=255;Reject(()=>PatchEngine.InstallCore(exe,true,null,p,null),"Corrupt patch accepted");Assert(PatchEngine.HashFile(exe)==PatchEngine.OriginalHash,"Corrupt patch wrote EXE");Assert(!Directory.Exists(Path.Combine(Path.GetDirectoryName(exe),"PCL","LocalRestoreBackups")),"Corrupt patch wrote backup");Sentinel(exe);});
  Test("changed executable after installation is never overwritten by restore",()=>{string exe=Case("newer-version");PatchEngine.Install(exe,true,null);var b=File.ReadAllBytes(exe);b[100]^=1;File.WriteAllBytes(exe,b);string changed=PatchEngine.HashFile(exe);Reject(()=>PatchEngine.Restore(exe),"Newer EXE overwritten");Assert(PatchEngine.HashFile(exe)==changed,"Newer EXE changed");Sentinel(exe);});
  Console.WriteLine("RESULT PASS: "+count+" tests; test save sentinels preserved.");
  File.WriteAllLines(Path.Combine(root,"results.txt"),results.Concat(new[]{"RESULT PASS: "+count+" tests; test save sentinels preserved."}),new UTF8Encoding(false));
 }
}
